C=z['classes']; y=z['y']; yi=np.searchsorted(C,y)
names=[k[4:] for k in z.files if k.startswith('oof_')]
print('models',names)

def assign50(p):
    slots=np.repeat(np.arange(6),50)
    costs=-np.log(np.clip(p[:,slots],1e-8,1))
    rr,cc=linear_sum_assignment(costs)
    out=np.empty(len(p),int); out[rr]=slots[cc]
    return out
rng=np.random.default_rng(123)
subsets=[]
for b in range(200):
 idx=np.concatenate([rng.choice(np.flatnonzero(yi==k),50,replace=False) for k in range(6)])
 rng.shuffle(idx); subsets.append(idx)

def ev(p):
 a=[]; c=[]
 for idx in subsets:
  a.append(f1_score(yi[idx],p[idx].argmax(1),average='macro'))
  c.append(f1_score(yi[idx],assign50(p[idx]),average='macro'))
 return np.mean(a),np.std(a),np.mean(c),np.std(c)
