const r = await tools.exec_command({
  cmd: "PYTHONUNBUFFERED=1 python3 - <<'PY'
import numpy as np,pandas as pd,time
from sklearn.preprocessing import StandardScaler,RobustScaler,QuantileTransformer
from sklearn.decomposition import PCA
from sklearn.model_selection import StratifiedKFold
from sklearn.neighbors import NearestNeighbors
from sklearn.metrics import f1_score
from scipy.optimize import linear_sum_assignment
from experiment_models import load_data,make_features
tr,te,cols=load_data(); C=np.array(sorted(tr.label.unique())); y=np.searchsorted(C,tr.label); raw=make_features(tr,cols,'raw'); rt=make_features(te,cols,'raw'); eng=make_features(tr,cols,'engineered'); et=make_features(te,cols,'engineered')
variants=[('raw_std',raw,rt,StandardScaler(),None),('raw_rob',raw,rt,RobustScaler(),None),('raw_pca10',raw,rt,StandardScaler(),10),('raw_pca18',raw,rt,StandardScaler(),18),('eng_std',eng,et,StandardScaler(),None),('eng_pca18',eng,et,StandardScaler(),18)]
cv=StratifiedKFold(5,shuffle=True,random_state=20250201); out={}
for name,X,Xt,scaler,pc in variants:
 st=time.time(); oof=np.zeros((len(X),6,50),np.float32); tst=np.zeros((len(Xt),6,50),np.float32)
 for f,(a,v) in enumerate(cv.split(X,y)):
  sc=type(scaler)(); xa=sc.fit_transform(X[a]); xv=sc.transform(X[v]); xt=sc.transform(Xt)
  if pc:
   q=PCA(pc,whiten=True,random_state=1).fit(xa);xa=q.transform(xa);xv=q.transform(xv);xt=q.transform(xt)
  for c in range(6):
   nn=NearestNeighbors(n_neighbors=min(50,np.sum(y[a]==c)),metric='euclidean',n_jobs=-1).fit(xa[y[a]==c])
   dv=nn.kneighbors(xv,return_distance=True)[0];dt=nn.kneighbors(xt,return_distance=True)[0]
   oof[v,c,:dv.shape[1]]=dv; oof[v,c,dv.shape[1]:]=dv[:,-1,None]
   tst[:,c,:dt.shape[1]]+=dt/5; tst[:,c,dt.shape[1]:]+=dt[:,-1,None]/5
  print(name,'fold',f+1,flush=True)
 out[name]=(oof,tst)
 print(name,'seconds',time.time()-st,flush=True)
# balanced subsets
rng=np.random.default_rng(3);subs=[]
for b in range(40):
 idx=np.concatenate([rng.choice(np.flatnonzero(y==c),50,replace=False) for c in range(6)]);rng.shuffle(idx);subs.append(idx)
def assign(s):
 slots=np.repeat(np.arange(6),50);rr,cc=linear_sum_assignment(-s[:,slots]);o=np.empty(300,int);o[rr]=slots[cc];return o
results=[]
for name,(oo,tt) in out.items():
 for k in [1,2,3,5,7,10,15,20,30,50]:
  # negative log mean distance; class scale alternatives
  d=oo[:,:,:k].mean(2);dt=tt[:,:,:k].mean(2)
  for norm in ['none','median','z']:
   if norm=='none':s=-np.log(d+1e-6);st=-np.log(dt+1e-6)
   elif norm=='median':
    med=np.array([np.median(d[y==c,c]) for c in range(6)]);s=-np.log(d/(med+1e-6)+1e-6);st=-np.log(dt/(med+1e-6)+1e-6)
   else:
    ld=np.log(d+1e-6); mu=np.array([np.mean(ld[y==c,c]) for c in range(6)]);sd=np.array([np.std(ld[y==c,c]) for c in range(6)]);s=-(ld-mu)/sd;st=-(np.log(dt+1e-6)-mu)/sd
   vals=[f1_score(y[idx],assign(s[idx]),average='macro') for idx in subs]
   results.append((np.mean(vals),np.std(vals),name,k,norm,st))
for j,r in enumerate(sorted(results,key=lambda x:x[0],reverse=True)[:20]):
 pred=assign(r[5]);A=pd.read_csv('candidate_01_diverse_balanced.csv').prediction.to_numpy();agree=np.mean(C[pred]==A)
 print(j,r[:5],'Aagree',agree,flush=True)
 if j<5:pd.DataFrame({'id':te.id,'prediction':C[pred]}).to_csv(f'classdist_candidate_{j}.csv',index=False)
PY",
